import java.util.*;

class ValidWordAbbr {
  private final Map<String, String> owner = new HashMap<>(); // abbreviation -> its word, or "" if shared

  public ValidWordAbbr(String[] dictionary) {
    for (String w : dictionary) {
      String a = abbr(w);
      String prev = owner.get(a);
      owner.put(a, prev == null || prev.equals(w) ? w : "");
    }
  }

  public boolean isUnique(String word) {
    String o = owner.get(abbr(word));
    return o == null || o.equals(word);
  }

  private String abbr(String w) {
    return w.length() <= 2 ? w : w.charAt(0) + String.valueOf(w.length() - 2) + w.charAt(w.length() - 1);
  }
}
